window.SEARCH_INDEX=[{"t":"Search","d":"Your phone and the web – in one place – One search bar for everything: apps, contacts, events, files, notes and settings on your phone, and answers, knowledge, places, movies and music from the web. Results appear while you type, and the search understands small typos and whole sentences like “appointments tomorrow” or “dentist Friday”.","u":"search.html","p":"Search","k":1},{"t":"The search bar","d":"The search bar is built to stay out of your way: multi-line input that reacts instantly, results that arrive together in one calm step, and controls right where your thumb is.","u":"search.html#bar","p":"Search","k":1},{"t":"Fast, calm, precise","d":"The input is decoupled from the content below, so typing never lags. Results follow after a short pause and appear together – no flickering lists.","u":"search.html#bar","p":"Search","k":0},{"t":"Search history","d":"Tap the empty field to see recent searches. Tap inserts a term, swipe sideways deletes it.","u":"search.html#bar","p":"Search","k":0},{"t":"Clipboard suggestion","d":"Text you just copied (at most three minutes old) can be searched, opened as a link or dismissed.","u":"search.html#bar","p":"Search","k":0},{"t":"Live suggestions","d":"Suggestions while you type; the arrow puts one into the field so you can keep editing.","u":"search.html#bar","p":"Search","k":0},{"t":"Keyboard on your terms","d":"Opens automatically always or only at app start. Long-press the keyboard button to switch auto-open off and on.","u":"search.html#bar","p":"Search","k":0},{"t":"Special searches","d":"One button opens address search, movies & music, or song recognition – shown filled while active.","u":"search.html#bar","p":"Search","k":0},{"t":"Quick search","d":"11 services one tap away – YouTube, YouTube Music, Amazon, ChatGPT, Gemini, Claude, Spotify, Wikipedia, OpenStreetMap, Maps and Play Store – as a row at the top or a bar above the keyboard.","u":"search.html#bar","p":"Search","k":0},{"t":"Details: Search bar shows the active search engine’s icon; tap it for a quick engine picker","d":"The search bar","u":"search.html#bar","p":"Search","k":0},{"t":"Details: Enter – also on hardware keyboards or with pasted text – starts the search instead of a line break","d":"The search bar","u":"search.html#bar","p":"Search","k":0},{"t":"Details: Clear button and a send button that changes shape when pressed","d":"The search bar","u":"search.html#bar","p":"Search","k":0},{"t":"Details: Quick search opens the service’s app or the browser; without the app it leads to the Play Store","d":"The search bar","u":"search.html#bar","p":"Search","k":0},{"t":"Details: Apps button next to the keyboard button opens the app drawer","d":"The search bar","u":"search.html#bar","p":"Search","k":0},{"t":"Details: Tapping a card, button or chip closes the keyboard","d":"The search bar","u":"search.html#bar","p":"Search","k":0},{"t":"Details: Haptic feedback on taps, toggles and swipes","d":"The search bar","u":"search.html#bar","p":"Search","k":0},{"t":"Search your phone","d":"Local search runs in the background and never leaves your device. You decide which sections appear and in which order.","u":"search.html#local","p":"Search","k":1},{"t":"Calculator & units","d":"Basic arithmetic, brackets, powers, percent and “X % of Y”, functions like sqrt, sin, cos, tan, log and ln – plus conversions like “5 km to mi” for length, weight, volume, temperature, area, speed and data sizes.","u":"search.html#local","p":"Search","k":0},{"t":"Calendar","d":"Title and location of events in the calendars you choose. Understands today, tomorrow, weekend, next week and dates like 24.12.","u":"search.html#local","p":"Search","k":0},{"t":"Settings shortcuts","d":"Jump straight to about 40 Android settings pages – hotspot, VPN, battery saver, Do not disturb, developer options and more. Keywords in English and German, slang included.","u":"search.html#local","p":"Search","k":0},{"t":"Apps & shortcuts","d":"Find and launch installed apps, typo-tolerant, with up to 8 hits. App shortcuts are searchable too; hidden apps stay hidden.","u":"search.html#local","p":"Search","k":0},{"t":"Contacts","d":"Names and emails typo-tolerant, phone numbers from 3 digits. Tap opens a rich contact sheet.","u":"search.html#local","p":"Search","k":0},{"t":"Files & media","d":"Files on the device with thumbnails, colored file-type icons and shortened paths. Install APK files directly.","u":"search.html#local","p":"Search","k":0},{"t":"Notes","d":"Finds text in your own notes. Type “Note …” to save the rest as a new note right from the search bar.","u":"search.html#local","p":"Search","k":0},{"t":"Calculator: Notations ×, ÷, ·, comma as decimal sign, colon as divide, implicit multiplication before brackets","d":"Search your phone","u":"search.html#local","p":"Search","k":0},{"t":"Calculator: Units written out in English and German (miles, inch, pound, gallon …)","d":"Search your phone","u":"search.html#local","p":"Search","k":0},{"t":"Calculator: Copy the result or open your calculator app","d":"Search your phone","u":"search.html#local","p":"Search","k":0},{"t":"Calendar: Date words: today, tomorrow, yesterday, day after tomorrow, this week, next week, weekend, weekdays","d":"Search your phone","u":"search.html#local","p":"Search","k":0},{"t":"Calendar: Swipe sideways hides an event – with undo","d":"Search your phone","u":"search.html#local","p":"Search","k":0},{"t":"Files: Full file access or only images, videos and audio","d":"Search your phone","u":"search.html#local","p":"Search","k":0},{"t":"Files: Number of results configurable","d":"Search your phone","u":"search.html#local","p":"Search","k":0},{"t":"Files: Open with the matching app","d":"Search your phone","u":"search.html#local","p":"Search","k":0},{"t":"Search the web","d":"Online, the search shows rich cards instead of a list of links – from Google Search or, if you prefer, entirely from free sources like Wikipedia, Wiktionary and Open-Meteo.","u":"search.html#web","p":"Search","k":1},{"t":"Weather with official warnings","d":"Temperature, condition and feels-like, an hourly forecast and days as tiles, expandable values for precipitation, wind, humidity and air quality – and official severe weather warnings of the German Weather Service with severity, duration and instructions.","u":"search.html#web","p":"Search","k":0},{"t":"Answers & knowledge","d":"Direct answers with source, knowledge cards with facts from Google or Wikipedia.","u":"search.html#web","p":"Search","k":0},{"t":"Dictionary","d":"For single words: part of speech, meanings, pronunciation and hyphenation from Wiktionary.","u":"search.html#web","p":"Search","k":0},{"t":"Top stories","d":"Current news with source and time.","u":"search.html#web","p":"Search","k":0},{"t":"Results without ads","d":"The first result large, the rest compact – and never an ad. Related questions go straight into the search field.","u":"search.html#web","p":"Search","k":0},{"t":"Pin any card","d":"Pin a card – like the weather – to your home screen. It shows its last state instantly and updates in the background.","u":"search.html#web","p":"Search","k":0},{"t":"Your search engine","d":"Google, Bing, DuckDuckGo, Startpage, Ecosia, Brave, Perplexity, Qwant – or up to 20 of your own.","u":"search.html#web","p":"Search","k":0},{"t":"More: Results of another search engine, parsed without ads, with a button to its results page","d":"Search the web","u":"search.html#web","p":"Search","k":0},{"t":"More: Each card’s open button leads to the matching app or the source","d":"Search the web","u":"search.html#web","p":"Search","k":0},{"t":"More: Numbers and texts roll or crossfade smoothly when they update","d":"Search the web","u":"search.html#web","p":"Search","k":0},{"t":"More: Optionally share your precise location for weather and places instead of guessing from your connection","d":"Search the web","u":"search.html#web","p":"Search","k":0},{"t":"More: Open results in a Custom Tab or your browser","d":"Search the web","u":"search.html#web","p":"Search","k":0},{"t":"Places & addresses","d":"Find places nearby and addresses anywhere – free from OpenStreetMap, without a key and without a limit.","u":"search.html#places","p":"Search","k":1},{"t":"21 kinds of places nearby","d":"Pharmacy, supermarket, bakery, fuel, charging station, ATM, restaurant, café, hospital, doctor, toilets, parking, post office, hotel and more – with opening hours like “closes at 8 pm”, phone, website, route and wheelchair access.","u":"search.html#places","p":"Search","k":0},{"t":"Address search","d":"Suggestions like in Google Maps with distance. Tap shows the place, the arrow starts a route, the star saves it as a favorite.","u":"search.html#places","p":"Search","k":0},{"t":"Home, Work & favorites","d":"Several addresses per type with an optional name. One tap starts the route; with several addresses a picker opens.","u":"search.html#places","p":"Search","k":0},{"t":"Your maps app","d":"Google Maps, the device’s maps app (Organic Maps, OsmAnd, CoMaps …) or OpenStreetMap in the browser. Google Maps links are rewritten for your choice.","u":"search.html#places","p":"Search","k":0},{"t":"Details: Source: OpenStreetMap (Photon) or the device’s place search","d":"Places & addresses","u":"search.html#places","p":"Search","k":0},{"t":"Details: Search automatically after a short pause or on button press","d":"Places & addresses","u":"search.html#places","p":"Search","k":0},{"t":"Details: Opening hours evaluated: open 24 hours, “closes at …”, “opens at …”","d":"Places & addresses","u":"search.html#places","p":"Search","k":0},{"t":"Details: Home, Work and favorites with their own name and icon, each can be turned off – the row never leaves gaps","d":"Places & addresses","u":"search.html#places","p":"Search","k":0},{"t":"Details: License note “© OpenStreetMap contributors” with link","d":"Places & addresses","u":"search.html#places","p":"Search","k":0},{"t":"Movies & music","d":"Look up movies, series, artists, albums and songs – with cast, track lists, trailers and where to stream them in your country.","u":"search.html#media","p":"Search","k":1},{"t":"Rich cards that open in place","d":"Poster or cover, introduction from Wikipedia, facts like release, director, cast, genre, seasons or label, album track lists from MusicBrainz – and buttons for the trailer, your streaming apps, JustWatch and IMDb.","u":"search.html#media","p":"Search","k":0},{"t":"Your own media","d":"Music and videos on your phone with title, artist, album, length and cover – played in your default player.","u":"search.html#media","p":"Search","k":0},{"t":"Online catalog","d":"Movies, series and music from Wikipedia and Wikidata, songs from MusicBrainz – even with typos and unfinished words.","u":"search.html#media","p":"Search","k":0},{"t":"Recognize a song","d":"One button starts Audile, Shazam or Google song search.","u":"search.html#media","p":"Search","k":0},{"t":"35 countries","d":"Streaming and music providers of your country, chosen automatically via SIM or language – or set by hand.","u":"search.html#media","p":"Search","k":0},{"t":"Streaming providers: Worldwide: Netflix, Prime Video, Disney+, Apple TV, HBO Max, Paramount+, Crunchyroll, MUBI, Pluto TV","d":"Movies & music","u":"search.html#media","p":"Search","k":0},{"t":"Streaming providers: Germany: Joyn, RTL+, WOW, MagentaTV, waipu.tv, ARD, ZDF, arte, 3sat","d":"Movies & music","u":"search.html#media","p":"Search","k":0},{"t":"Streaming providers: Austria: ORF ON · Switzerland: Play SRF, RTS, RSI","d":"Movies & music","u":"search.html#media","p":"Search","k":0},{"t":"Streaming providers: United Kingdom: BBC iPlayer, ITVX, Channel 4, NOW · USA: Hulu, Peacock, Tubi","d":"Movies & music","u":"search.html#media","p":"Search","k":0},{"t":"Streaming providers: Plus France, Italy, Spain, the Netherlands, India, Brazil, and Viki in Korea, Japan and Taiwan","d":"Movies & music","u":"search.html#media","p":"Search","k":0},{"t":"Music services: Worldwide: Spotify, YouTube Music, Apple Music, Tidal, Deezer, Amazon Music, Qobuz, SoundCloud, YouTube","d":"Movies & music","u":"search.html#media","p":"Search","k":0},{"t":"Music services: Regional: JioSaavn, Gaana, Anghami, Boomplay, Audiomack, Yandex Music, VK Music, Melon, LINE MUSIC, KKBOX, QQ Music","d":"Movies & music","u":"search.html#media","p":"Search","k":0},{"t":"Music services: Songs open straight at the track when its ID is known","d":"Movies & music","u":"search.html#media","p":"Search","k":0},{"t":"Home screen","d":"What matters, before you type – Before you type a single letter, Universal Search shows what is relevant right now: today’s events, the weather, your alarm, birthdays, music and notifications – and the apps, contacts and files you are most likely to need.","u":"home-screen.html","p":"Home screen","k":1},{"t":"Today","d":"The “Today” card is a calm overview of your day. Every part can be turned off, and parts without content simply disappear.","u":"home-screen.html#today","p":"Home screen","k":1},{"t":"Your day at a glance","d":"Date and a weather chip that opens the full weather card, the next event with “now running” or “in 45 min” and a route to it, all-day and further events via “+N” – plus your next alarm, birthdays with age and the route to work in the morning or home in the evening.","u":"home-screen.html#today","p":"Home screen","k":0},{"t":"Notifications","d":"The last two notifications – tap opens, swipe also removes them from the status bar. A 48-hour history grouped by app.","u":"home-screen.html#today","p":"Home screen","k":0},{"t":"Weather","d":"Refreshes silently in the background; until then the last state is shown.","u":"home-screen.html#today","p":"Home screen","k":0},{"t":"Alarm & birthdays","d":"Re-read whenever you come back, so the overview is always current.","u":"home-screen.html#today","p":"Home screen","k":0},{"t":"Music","d":"The music card is always there – also in the online tab.","u":"home-screen.html#music","p":"Home screen","k":1},{"t":"What’s playing","d":"Cover, title, artist and app icon with previous, play/pause and next – the cover fills the card in its own color, with a little wave while it plays.","u":"home-screen.html#music","p":"Home screen","k":0},{"t":"Nothing playing?","d":"Your preferred music service with its logo, its own shortcuts, suggestions like liked songs or Supermix, and recently played.","u":"home-screen.html#music","p":"Home screen","k":0},{"t":"Not installed yet","d":"An “Install” button leads straight to the store. With Bluetooth headphones connected: “Continue listening”.","u":"home-screen.html#music","p":"Home screen","k":0},{"t":"Everything else","d":"Order and visibility of all home sections are yours – arrange them in the layout editor.","u":"home-screen.html#sections","p":"Home screen","k":1},{"t":"Agenda","d":"Upcoming events like in Google Calendar – weekday above the day number, today in a circle, calendar color strip. Swipe away what you don’t need.","u":"home-screen.html#sections","p":"Home screen","k":0},{"t":"App suggestions","d":"Suggested and frequently used apps, with a button to all apps.","u":"home-screen.html#sections","p":"Home screen","k":0},{"t":"Frequent contacts","d":"One tap opens the contact sheet with all ways to reach someone.","u":"home-screen.html#sections","p":"Home screen","k":0},{"t":"Recent files","d":"Recently opened files; the number is up to you.","u":"home-screen.html#sections","p":"Home screen","k":0},{"t":"Notes","d":"Your newest notes directly on the home screen, the rest via “All notes”.","u":"home-screen.html#sections","p":"Home screen","k":0},{"t":"Pinned cards","d":"Cards you pinned from the web search – each can be moved and hidden.","u":"home-screen.html#sections","p":"Home screen","k":0},{"t":"Launcher widgets","d":"Widgets of your installed apps as cards, with adjustable height.","u":"home-screen.html#sections","p":"Home screen","k":0},{"t":"Home · Work · Favorites","d":"Your places one tap away, each with its own name and icon.","u":"home-screen.html#sections","p":"Home screen","k":0},{"t":"AI Assistant","d":"Optional – with your own key – The AI assistant is optional and off by default. Unlock it in the developer options, add your own API key – and you get a chat that searches the web, understands your local data when you allow it, and prepares actions that only run when you tap.","u":"ai.html","p":"AI Assistant","k":1},{"t":"The chat","d":"The whole window becomes a chat of stacked cards, centered with a readable line length on tablets. Ask follow-up questions, stop, try again or start fresh – and switch provider and model right in the chat.","u":"ai.html#chat","p":"AI Assistant","k":1},{"t":"A chat that fits the app","d":"The whole window becomes a chat of stacked cards, centered with a readable line length on tablets. Ask follow-up questions, stop, try again or start fresh – and switch provider and model right in the chat.","u":"ai.html#chat","p":"AI Assistant","k":0},{"t":"Images","d":"Attach up to four images per message from your gallery or camera – with preview and full view.","u":"ai.html#chat","p":"AI Assistant","k":0},{"t":"Rich answers","d":"Bold, lists, headings, quotes, code blocks, tables, images and checkboxes you can tick.","u":"ai.html#chat","p":"AI Assistant","k":0},{"t":"Transparent steps","d":"Collapsible steps like “searched” and “read”, live status while answering, and sources as chips.","u":"ai.html#chat","p":"AI Assistant","k":0},{"t":"Read aloud","d":"Copy, share or have answers spoken with your system voice.","u":"ai.html#chat","p":"AI Assistant","k":0},{"t":"Cards in answers","d":"Events, contacts, files, weather, places, news and saved addresses appear as cards, just like in search.","u":"ai.html#chat","p":"AI Assistant","k":0},{"t":"Carried over","d":"Whatever you typed in the search bar is carried into the chat when you switch.","u":"ai.html#chat","p":"AI Assistant","k":0},{"t":"Eight providers","d":"Use the provider you trust – with your own key. Gemini Flash-Lite can be used for free.","u":"ai.html#providers","p":"AI Assistant","k":1},{"t":"Your key, your choice","d":"Google Gemini, Groq, OpenRouter, Mistral, OpenAI, Anthropic, Perplexity and DeepSeek. Models load automatically with the key; filter them, show only free ones, or hide preview versions.","u":"ai.html#providers","p":"AI Assistant","k":0},{"t":"Keys stay safe","d":"Encrypted in the Android Keystore and never part of backups.","u":"ai.html#providers","p":"AI Assistant","k":0},{"t":"Clear labels","d":"“Free to use” or “Paid”, a “Get key” link and a connection test.","u":"ai.html#providers","p":"AI Assistant","k":0},{"t":"Web search & local data","d":"The AI searches and reads pages itself: Gemini via Google Search, others via their own search or the app’s (DuckDuckGo, Bing, Wikipedia). For Gemini the search starts while you are still typing, and links in your question are opened and read.","u":"ai.html#web","p":"AI Assistant","k":1},{"t":"Grounded in the web","d":"The AI searches and reads pages itself: Gemini via Google Search, others via their own search or the app’s (DuckDuckGo, Bing, Wikipedia). For Gemini the search starts while you are still typing, and links in your question are opened and read.","u":"ai.html#web","p":"AI Assistant","k":0},{"t":"Local data – one by one","d":"Calendar, contacts, call log, files, apps, device status, notes, Home & Work. Each is allowed separately, and only the result goes to the provider.","u":"ai.html#web","p":"AI Assistant","k":0},{"t":"Location on request","d":"Country only, or country and precise location – only when needed and only to the provider you chose.","u":"ai.html#web","p":"AI Assistant","k":0},{"t":"Actions","d":"The assistant prepares, you decide. Nothing happens without your tap.","u":"ai.html#actions","p":"AI Assistant","k":1},{"t":"Events","d":"Create calendar events, pre-filled from the conversation.","u":"ai.html#actions","p":"AI Assistant","k":0},{"t":"Alarms & timers","d":"Optionally set directly; everything else opens pre-filled.","u":"ai.html#actions","p":"AI Assistant","k":0},{"t":"Calls & messages","d":"Call, write an SMS or an email – calls and SMS always need your tap.","u":"ai.html#actions","p":"AI Assistant","k":0},{"t":"Routes","d":"Start a route in your maps app.","u":"ai.html#actions","p":"AI Assistant","k":0},{"t":"Apps","d":"Open apps and share content.","u":"ai.html#actions","p":"AI Assistant","k":0},{"t":"Notes","d":"Save a note right from the chat; the AI can also search your notes.","u":"ai.html#actions","p":"AI Assistant","k":0},{"t":"Continue anywhere: Hand the conversation over to ChatGPT, Gemini, Claude, Perplexity, Le Chat or DeepSeek","d":"Actions","u":"ai.html#actions","p":"AI Assistant","k":0},{"t":"Continue anywhere: Optionally summarized by the AI first – the summary is also copied to the clipboard","d":"Actions","u":"ai.html#actions","p":"AI Assistant","k":0},{"t":"Personalize","d":"Tabs, layout, design and widgets – your way – Universal Search adapts to you: two tabs you name and fill yourself, a layout editor for every surface, Material 3 Expressive design with your colors, a home screen widget and deep Android integration.","u":"personalize.html","p":"Personalize","k":1},{"t":"Two custom tabs","d":"Start with “Local” and “Online” – or build something completely different. Every tab has its own home screen and its own search sections; any element can go into any tab, even several times.","u":"personalize.html#tabs","p":"Personalize","k":1},{"t":"Each tab, its own world","d":"Start with “Local” and “Online” – or build something completely different. Every tab has its own home screen and its own search sections; any element can go into any tab, even several times.","u":"personalize.html#tabs","p":"Personalize","k":0},{"t":"Name & icon","d":"A free name and a free icon: over 90 Material symbols with search, any emoji, or your own image (SVG, PNG, JPG, WebP, GIF, HEIF …).","u":"personalize.html#tabs","p":"Personalize","k":0},{"t":"Per tab","d":"Keep the home screen below the results while typing, and choose which special searches the tab offers.","u":"personalize.html#tabs","p":"Personalize","k":0},{"t":"Switch your way","d":"Use the buttons below the search bar or swipe left and right anywhere – sideways lists take priority.","u":"personalize.html#tabs","p":"Personalize","k":0},{"t":"Smooth transitions","d":"Switching tabs is a full-screen crossfade: what stays the same does not move.","u":"personalize.html#tabs","p":"Personalize","k":0},{"t":"Layout editor","d":"A full-screen editor for four surfaces: home and search of each tab – shown exactly in the shape of your screen, with sample data.","u":"personalize.html#layout","p":"Personalize","k":1},{"t":"Move cards like widgets","d":"Long-press and drag to move, tap for an element’s options, add any element to any surface – even several times. Changes apply when you tap Save. The top area with tabs, navigation buttons and quick search stays fixed.","u":"personalize.html#layout","p":"Personalize","k":0},{"t":"Launcher widgets","d":"Add widgets of your installed apps as cards and adjust their height.","u":"personalize.html#layout","p":"Personalize","k":0},{"t":"Hide & restore","d":"Hidden elements are kept aside and can be shown again any time.","u":"personalize.html#layout","p":"Personalize","k":0},{"t":"Tablets & foldables","d":"Full width and two columns on tablets; foldables are arranged separately for outside and inside.","u":"personalize.html#layout","p":"Personalize","k":0},{"t":"Permission hints","d":"An element that lacks a permission says so – tap to grant it.","u":"personalize.html#layout","p":"Personalize","k":0},{"t":"Design","d":"Own shapes and color roles per area, stacked cards and shape animations. Choose Material You, one of nine color themes – blue, green, red, orange, yellow, turquoise, purple, pink – or any color you like.","u":"personalize.html#design","p":"Personalize","k":1},{"t":"Material 3 Expressive","d":"Own shapes and color roles per area, stacked cards and shape animations. Choose Material You, one of nine color themes – blue, green, red, orange, yellow, turquoise, purple, pink – or any color you like.","u":"personalize.html#design","p":"Personalize","k":0},{"t":"Light, dark & AMOLED","d":"Automatic or fixed, with an extra dark mode in true black.","u":"personalize.html#design","p":"Personalize","k":0},{"t":"Wallpaper","d":"Your wallpaper behind the cards – brighten or darken it separately for light and dark mode.","u":"personalize.html#design","p":"Personalize","k":0},{"t":"Blur","d":"Blur behind cards, menus and wallpaper, per group with its own intensity.","u":"personalize.html#design","p":"Personalize","k":0},{"t":"Details","d":"Rounded outline icons only, original logos of services, weather icons in the app’s style and colored file-type icons.","u":"personalize.html#design","p":"Personalize","k":0},{"t":"Widget & tiles","d":"Tap opens the search instantly, without a splash screen. Choose the buttons – Google Lens, voice search, Gemini, music – and an optional round button for music or Maps.","u":"personalize.html#widget","p":"Personalize","k":1},{"t":"Search bar widget","d":"Tap opens the search instantly, without a splash screen. Choose the buttons – Google Lens, voice search, Gemini, music – and an optional round button for music or Maps.","u":"personalize.html#widget","p":"Personalize","k":0},{"t":"Your widget design","d":"System colors, nine color themes, Nothing OS style or a custom color; brightness, AMOLED, corner radius and transparency – with live preview.","u":"personalize.html#widget","p":"Personalize","k":0},{"t":"Quick Settings tiles","d":"Two “Search” tiles open the search right from the notification shade.","u":"personalize.html#widget","p":"Personalize","k":0},{"t":"Always current","d":"Reacts to night mode and new Material You colors and redraws after a reboot.","u":"personalize.html#widget","p":"Personalize","k":0},{"t":"Android integration","d":"","u":"personalize.html#system","p":"Personalize","k":1},{"t":"Digital assistant","d":"Set Universal Search as your assistant app – also via the voice command key.","u":"personalize.html#system","p":"Personalize","k":0},{"t":"Instant start","d":"No splash from widget, tiles and assistant; from the app icon only until the home screen is ready.","u":"personalize.html#system","p":"Personalize","k":0},{"t":"Tablets & foldables","d":"Own layouts with columns; on foldables phone view outside, tablet view inside.","u":"personalize.html#system","p":"Personalize","k":0},{"t":"20 languages","d":"Follows your system or set per app; AI-translated languages are labeled.","u":"personalize.html#system","p":"Personalize","k":0},{"t":"Themed icon","d":"The app icon follows your wallpaper colors, with a monochrome version for themed icons.","u":"personalize.html#system","p":"Personalize","k":0},{"t":"Update check","d":"Checks GitHub releases and shows the status in the settings.","u":"personalize.html#system","p":"Personalize","k":0},{"t":"Organize","d":"Apps, notes and details – neatly sorted – Beyond search, Universal Search keeps your apps tidy, your notes at hand and every detail of a contact, event or file one tap away.","u":"organize.html","p":"Organize","k":1},{"t":"App drawer","d":"Favorites, folders and recently used apps at the top – and always all apps from A to Z below. Filter by name while the sheet keeps its full height.","u":"organize.html#drawer","p":"Organize","k":1},{"t":"Everything in its place","d":"Favorites, folders and recently used apps at the top – and always all apps from A to Z below. Filter by name while the sheet keeps its full height.","u":"organize.html#drawer","p":"Organize","k":0},{"t":"Folders","d":"Up to four app icons as preview. Create, rename, add or remove apps with checkmarks, delete.","u":"organize.html#drawer","p":"Organize","k":0},{"t":"Favorites","d":"An app can be in favorites and folders and still stays in the A–Z list.","u":"organize.html#drawer","p":"Organize","k":0},{"t":"Self-cleaning","d":"Uninstalled apps disappear from favorites and folders automatically.","u":"organize.html#drawer","p":"Organize","k":0},{"t":"Columns","d":"Four columns on phones, six on tablets.","u":"organize.html#drawer","p":"Organize","k":0},{"t":"Notes","d":"Quick notes as cards on your home screen with title, preview and ticked boxes like 2/5. A formatted view with checkboxes you can tick, and an editor with a toolbar right above the keyboard.","u":"organize.html#notes","p":"Organize","k":1},{"t":"Write it down, find it later","d":"Quick notes as cards on your home screen with title, preview and ticked boxes like 2/5. A formatted view with checkboxes you can tick, and an editor with a toolbar right above the keyboard.","u":"organize.html#notes","p":"Organize","k":0},{"t":"Lists that continue","d":"Bullets and numbers continue on a new line; an empty line ends the list.","u":"organize.html#notes","p":"Organize","k":0},{"t":"Toolbar","d":"Checkbox, lists, heading, bold, italic, strikethrough, code, quote, divider, indent and outdent.","u":"organize.html#notes","p":"Organize","k":0},{"t":"Searchable","d":"Notes are part of the search; type “Note …” to save a new one directly.","u":"organize.html#notes","p":"Organize","k":0},{"t":"Saved as you type","d":"Copy, share or delete – nothing gets lost.","u":"organize.html#notes","p":"Organize","k":0},{"t":"Detail sheets","d":"Long-press or tap a result to see everything about it.","u":"organize.html#details","p":"Organize","k":1},{"t":"Apps","d":"App info, pin, hide, uninstall, the app’s shortcuts, favorites and folders.","u":"organize.html#details","p":"Organize","k":0},{"t":"Contacts","d":"Call, SMS, video, mail; numbers, addresses with route, websites, birthdays, recent calls – and messengers like Signal, Telegram, Threema and WhatsApp.","u":"organize.html#details","p":"Organize","k":0},{"t":"Events","d":"When, where with route, notes, reminders, attendees with their status, availability and calendar.","u":"organize.html#details","p":"Organize","k":0},{"t":"Files","d":"Open in the matching app or install an APK with a permission hint.","u":"organize.html#details","p":"Organize","k":0},{"t":"Privacy","d":"Your data, your rules – Universal Search has no account, no analytics, no ads and no tracking, and runs no servers of its own. Searches on your phone stay on your phone; online requests go directly from your device to the service you chose – and you can switch them off.","u":"privacy-features.html","p":"Privacy","k":1},{"t":"Free providers only","d":"Turn on “Free providers only” and the app makes no requests to Google or other proprietary services: weather comes from Open-Meteo, knowledge from Wikipedia, places from OpenStreetMap, maps open in a maps app. The AI can still be allowed separately – then without web search.","u":"privacy-features.html#free","p":"Privacy","k":1},{"t":"One switch for open sources","d":"Turn on “Free providers only” and the app makes no requests to Google or other proprietary services: weather comes from Open-Meteo, knowledge from Wikipedia, places from OpenStreetMap, maps open in a maps app. The AI can still be allowed separately – then without web search.","u":"privacy-features.html#free","p":"Privacy","k":0},{"t":"Permissions on your terms","d":"Every permission is explained in an info dialog. Internet and app search can be switched off inside the app.","u":"privacy-features.html#free","p":"Privacy","k":0},{"t":"No ads","d":"Result cards never contain ads.","u":"privacy-features.html#free","p":"Privacy","k":0},{"t":"Keys stay safe","d":"API keys are encrypted in the Android Keystore and never part of backups.","u":"privacy-features.html#free","p":"Privacy","k":0},{"t":"Stays on your device","d":"Notification history and recently played music are never included in backups.","u":"privacy-features.html#free","p":"Privacy","k":0},{"t":"AI only when allowed","d":"The AI reads local data only when you allowed it and it is needed for the question; only the result goes to the provider.","u":"privacy-features.html#free","p":"Privacy","k":0},{"t":"Location on request","d":"Precise location only when you turn it on, and only to the provider you chose.","u":"privacy-features.html#free","p":"Privacy","k":0},{"t":"Read more: The full privacy policy of the app explains every service the app talks to – see “App privacy” in the footer.","d":"Free providers only","u":"privacy-features.html#free","p":"Privacy","k":0},{"t":"For organizations","d":"Open source, privacy-friendly, free – Universal Search is a good fit wherever privacy matters – in companies, public offices, schools or associations. It needs no account and no server, collects nothing, and its source code is open for everyone to review.","u":"organizations.html","p":"For organizations","k":1},{"t":"Why it fits","d":"Use, modify and distribute the app – also commercially and inside your organization. The license is permissive and well known to legal departments.","u":"organizations.html#why","p":"For organizations","k":1},{"t":"Apache License 2.0","d":"Use, modify and distribute the app – also commercially and inside your organization. The license is permissive and well known to legal departments.","u":"organizations.html#why","p":"For organizations","k":0},{"t":"No data collection","d":"No analytics, no crash reporting, no ads, no tracking – and no own servers that could store anything.","u":"organizations.html#why","p":"For organizations","k":0},{"t":"Open sources only","d":"“Free providers only” keeps devices away from proprietary services: Open-Meteo, Wikipedia and OpenStreetMap instead.","u":"organizations.html#why","p":"For organizations","k":0},{"t":"Controllable network use","d":"Internet access and app search can be switched off inside the app; every permission is optional and explained.","u":"organizations.html#why","p":"For organizations","k":0},{"t":"Auditable","d":"The complete Kotlin source code is on GitHub – your IT can review and build it.","u":"organizations.html#why","p":"For organizations","k":0},{"t":"Phones, tablets, foldables","d":"One app for every form factor, from Android 14.","u":"organizations.html#why","p":"For organizations","k":0},{"t":"20 languages","d":"For international teams – each person can choose their own app language.","u":"organizations.html#why","p":"For organizations","k":0},{"t":"Questions?","d":"Questions about using Universal Search in your organization are welcome in the Telegram group or via the contact details in the imprint.","u":"organizations.html#contact","p":"For organizations","k":1},{"t":"Download","d":"Android 14 or newer · free and open source – Universal Search is free and open source. Download the latest release from GitHub, install it, and make it yours.","u":"download.html","p":"Download","k":1},{"t":"Install in three steps","d":"","u":"download.html#install","p":"Download","k":1},{"t":"1 · Download","d":"Get the APK of the latest release from GitHub.","u":"download.html#install","p":"Download","k":0},{"t":"2 · Install","d":"Open the file and allow installing apps from your browser or file manager if Android asks.","u":"download.html#install","p":"Download","k":0},{"t":"3 · Make it yours","d":"Choose your tabs, colors and the permissions you want to give – everything is optional.","u":"download.html#install","p":"Download","k":0},{"t":"Good to know","d":"","u":"download.html#faq","p":"Download","k":1},{"t":"Requirements: Android 14 or newer","d":"Good to know","u":"download.html#faq","p":"Download","k":0},{"t":"Requirements: Phones, tablets and foldables","d":"Good to know","u":"download.html#faq","p":"Download","k":0},{"t":"Requirements: Internet is optional – local search works without it","d":"Good to know","u":"download.html#faq","p":"Download","k":0},{"t":"Updates: The app checks GitHub releases and shows the update status in the settings","d":"Good to know","u":"download.html#faq","p":"Download","k":0},{"t":"Updates: All settings of the earlier Flutter version are taken over automatically","d":"Good to know","u":"download.html#faq","p":"Download","k":0},{"t":"Permissions: Internet and installed apps (both can be switched off in the app)","d":"Good to know","u":"download.html#faq","p":"Download","k":0},{"t":"Permissions: Files, calendar, contacts, call log and location – each optional","d":"Good to know","u":"download.html#faq","p":"Download","k":0},{"t":"Permissions: Notification access for the history on the home screen","d":"Good to know","u":"download.html#faq","p":"Download","k":0},{"t":"Permissions: Every permission is explained in the app","d":"Good to know","u":"download.html#faq","p":"Download","k":0},{"t":"Works with","d":"Services and providers built right in","u":"works-with.html","p":"Works with","k":1},{"t":"Google · Google LLC","d":"Results, live suggestions and rich web cards: direct answers, knowledge, top stories, places and weather. Search Suggestions Web cards","u":"works-with.html#search","p":"Works with","k":0},{"t":"Bing · Microsoft","d":"Search results and live suggestions; also one of the web sources the AI assistant can read. Search Suggestions","u":"works-with.html#search","p":"Works with","k":0},{"t":"DuckDuckGo · Duck Duck Go, Inc.","d":"Privacy-focused search without personal profiles; also used by the AI assistant’s own web search. Search Privacy","u":"works-with.html#search","p":"Works with","k":0},{"t":"Ecosia · Ecosia GmbH","d":"The search engine that uses its profits to plant trees. Search Europe","u":"works-with.html#search","p":"Works with","k":0},{"t":"Brave Search · Brave Software","d":"Search with its own independent index and live suggestions. Search Suggestions Privacy","u":"works-with.html#search","p":"Works with","k":0},{"t":"Startpage · Startpage B.V.","d":"Google results without tracking, from the Netherlands. Search Privacy Europe","u":"works-with.html#search","p":"Works with","k":0},{"t":"Qwant · Qwant SAS","d":"European search engine from France, with live suggestions. Search Suggestions Europe","u":"works-with.html#search","p":"Works with","k":0},{"t":"Perplexity · Perplexity AI","d":"An answer engine as your search – and also available as an AI provider. Search AI","u":"works-with.html#search","p":"Works with","k":0},{"t":"Gemini · Google","d":"Answers grounded in Google Search; the live search starts while you type. Gemini Flash-Lite can be used for free. Needs API key Free model Web search","u":"works-with.html#ai","p":"Works with","k":0},{"t":"ChatGPT · OpenAI","d":"OpenAI models with web search; continue a conversation in the ChatGPT app. Needs API key Web search","u":"works-with.html#ai","p":"Works with","k":0},{"t":"Claude · Anthropic","d":"Anthropic’s Claude models with web search; hand conversations over to the Claude app. Needs API key Web search","u":"works-with.html#ai","p":"Works with","k":0},{"t":"Mistral · Mistral AI","d":"Models from Paris; continue in Le Chat. Needs API key Europe","u":"works-with.html#ai","p":"Works with","k":0},{"t":"Groq · Groq, Inc.","d":"Very fast responses from open models. Needs API key Fast","u":"works-with.html#ai","p":"Works with","k":0},{"t":"OpenRouter · OpenRouter, Inc.","d":"Hundreds of models through a single key – filter for free ones right in the app. Needs API key Many models","u":"works-with.html#ai","p":"Works with","k":0},{"t":"DeepSeek · DeepSeek","d":"DeepSeek’s chat and reasoning models. Needs API key","u":"works-with.html#ai","p":"Works with","k":0},{"t":"Perplexity · Perplexity AI","d":"Answers with web search built into the model, with sources. Needs API key Web search","u":"works-with.html#ai","p":"Works with","k":0},{"t":"Spotify · Spotify AB","d":"Music card with shortcuts, songs from the search open straight at the track. Music card Song links","u":"works-with.html#music","p":"Works with","k":0},{"t":"YouTube Music · Google","d":"Music card with suggestions like Supermix and liked songs. Music card Song links","u":"works-with.html#music","p":"Works with","k":0},{"t":"Apple Music · Apple","d":"Songs and albums from the search open in Apple Music. Song links","u":"works-with.html#music","p":"Works with","k":0},{"t":"Amazon Music · Amazon","d":"Songs and albums from the search open in Amazon Music. Song links","u":"works-with.html#music","p":"Works with","k":0},{"t":"Deezer · Deezer SA","d":"Songs and albums from the search open in Deezer. Song links Europe","u":"works-with.html#music","p":"Works with","k":0},{"t":"Tidal · TIDAL","d":"High-fidelity streaming; songs from the search open in Tidal. Song links","u":"works-with.html#music","p":"Works with","k":0},{"t":"Qobuz · Xandrie SA","d":"Hi-res streaming from France; songs open in Qobuz. Song links Europe","u":"works-with.html#music","p":"Works with","k":0},{"t":"SoundCloud · SoundCloud","d":"Independent artists and mixes; searches open in SoundCloud. Song links","u":"works-with.html#music","p":"Works with","k":0},{"t":"YouTube · Google","d":"Always available for songs – and for movie trailers. Song links Trailers","u":"works-with.html#music","p":"Works with","k":0},{"t":"Shazam · Apple","d":"Recognize the song that is playing with one button. Recognition","u":"works-with.html#music","p":"Works with","k":0},{"t":"Audile · Open source","d":"An open-source app for song recognition – one of the choices for the recognize button. Recognition Open source","u":"works-with.html#music","p":"Works with","k":0},{"t":"Netflix · Netflix, Inc.","d":"Opens titles in the Netflix app when it is installed. Streaming","u":"works-with.html#streaming","p":"Works with","k":0},{"t":"Prime Video · Amazon","d":"Opens titles in Prime Video when it is installed. Streaming","u":"works-with.html#streaming","p":"Works with","k":0},{"t":"Disney+ · The Walt Disney Company","d":"Opens titles in Disney+ when it is installed. Streaming","u":"works-with.html#streaming","p":"Works with","k":0},{"t":"Joyn · Joyn GmbH","d":"German streaming service – one of the providers for Germany and Austria. Streaming Regional","u":"works-with.html#streaming","p":"Works with","k":0},{"t":"RTL+ · RTL Deutschland","d":"German streaming service – one of the providers for Germany. Streaming Regional","u":"works-with.html#streaming","p":"Works with","k":0},{"t":"JustWatch · JustWatch GmbH","d":"“Where to stream?” – shows where a title is available in your country’s catalog. Where to stream","u":"works-with.html#streaming","p":"Works with","k":0},{"t":"IMDb · Amazon","d":"Ratings, cast and details – one tap from every movie card. Movie info","u":"works-with.html#streaming","p":"Works with","k":0},{"t":"Wikipedia · Wikimedia Foundation","d":"Knowledge cards and introductions for movies, series, artists and albums. Knowledge Free provider","u":"works-with.html#knowledge","p":"Works with","k":0},{"t":"Open-Meteo · Open-Meteo","d":"Free weather forecast: hourly, daily, precipitation, wind and air quality. Weather Free provider Open source","u":"works-with.html#knowledge","p":"Works with","k":0},{"t":"OpenStreetMap · OpenStreetMap Foundation","d":"Places nearby and address suggestions – free, without a key and without a limit. Places Free provider Open data","u":"works-with.html#knowledge","p":"Works with","k":0},{"t":"Google Maps · Google","d":"One of the maps apps for places and routes – links are rewritten for your choice. Maps","u":"works-with.html#knowledge","p":"Works with","k":0},{"t":"Amazon · Amazon","d":"Shopping searches one tap away in the quick search. Quick search","u":"works-with.html#knowledge","p":"Works with","k":0}];
